import functools
from collections.abc import Callable, Iterable, Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from enum import Enum, auto
from functools import singledispatch
from itertools import islice
from typing import Any, Protocol, runtime_checkable

# ----------------------------------------------------------------------
# Supplied. Do not change anything in this block.
# ----------------------------------------------------------------------
JOURNAL: list[str] = []
LOG: list[str] = []
RELAY_ATTEMPTS: list[str] = []
STRATEGIES = {"vent": 3, "isolate": 7, "shutdown": 5}


class TransitionError(Exception):
    pass


class RelayError(Exception):
    pass


@dataclass(frozen=True)
class Reading:
    sensor: str
    value: float


@dataclass(frozen=True)
class Alarm:
    code: str


def audit(channel: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            LOG.append(f"{channel}: calling {func.__name__}")
            return func(*args, **kwargs)
        return wrapper
    return decorate


def retry(times: int) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except RelayError as exc:
                    last = exc
            raise last
        return wrapper
    return decorate


def relay_state(reading: Reading) -> bool:
    """Read the relay. It bounces the first two times."""
    RELAY_ATTEMPTS.append(reading.sensor)
    if len(RELAY_ATTEMPTS) < 3:
        raise RelayError(f"{reading.sensor} bounced")
    return reading.value < 5.0
# ----------------------------------------------------------------------
# End of the supplied block.
# ----------------------------------------------------------------------


# ======================================================================
# DELETE EVERY LINE BETWEEN THE TWO BANNERS. Do not translate it.
# ======================================================================
class AbstractHandler:
    def __init__(self, successor=None):
        self.successor = successor

    def handle(self, record):
        raise NotImplementedError

    def accept(self, visitor):
        return visitor.visit(self)


class PressureHandler(AbstractHandler):
    def handle(self, record):
        return record.value < 90.0


class TemperatureHandler(AbstractHandler):
    def handle(self, record):
        return record.value < 70.0


class RelayHandler(AbstractHandler):
    def handle(self, record):
        return relay_state(record)


class HandlerRegistry:
    _instance = None

    @classmethod
    def getInstance(cls):
        if cls._instance is None:
            cls._instance = HandlerRegistry()
        return cls._instance

    def lookup(self, name):
        if name == "pressure":
            return PressureHandler()
        elif name == "temperature":
            return TemperatureHandler()
        elif name == "relay":
            return RelayHandler()
        raise KeyError(name)


class StateInterface:
    def next_state(self, action):
        raise NotImplementedError


class IdleState(StateInterface):
    def next_state(self, action):
        if action == "arm":
            return ArmedState()
        raise ValueError(action)


class ArmedState(StateInterface):
    def next_state(self, action):
        if action == "start":
            return RunningState()
        raise ValueError(action)


class RunningState(StateInterface):
    def next_state(self, action):
        if action == "trip" or action == "stop":
            return StoppedState()
        raise ValueError(action)


class StoppedState(StateInterface):
    def next_state(self, action):
        if action == "reset":
            return IdleState()
        raise ValueError(action)
