import functools
from collections.abc import Callable, Iterable, Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from enum import Enum, auto
from functools import singledispatch
from itertools import islice
from typing import Any, Protocol, runtime_checkable

# ----------------------------------------------------------------------
# Supplied. Do not change anything in this block.
# ----------------------------------------------------------------------
JOURNAL: list[str] = []
LOG: list[str] = []
RELAY_ATTEMPTS: list[str] = []
STRATEGIES = {"vent": 3, "isolate": 7, "shutdown": 5}


class TransitionError(Exception):
    pass


class RelayError(Exception):
    pass


@dataclass(frozen=True)
class Reading:
    sensor: str
    value: float


@dataclass(frozen=True)
class Alarm:
    code: str


def audit(channel: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            LOG.append(f"{channel}: calling {func.__name__}")
            return func(*args, **kwargs)
        return wrapper
    return decorate


def retry(times: int) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorate(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except RelayError as exc:
                    last = exc
            raise last
        return wrapper
    return decorate


def relay_state(reading: Reading) -> bool:
    """Read the relay. It bounces the first two times."""
    RELAY_ATTEMPTS.append(reading.sensor)
    if len(RELAY_ATTEMPTS) < 3:
        raise RelayError(f"{reading.sensor} bounced")
    return reading.value < 5.0
# ----------------------------------------------------------------------
# End of the supplied block.
# ----------------------------------------------------------------------


HANDLERS: dict[str, Callable[[Reading], bool]] = {}


def handler(name: str) -> Callable[[Callable[[Reading], bool]], Callable[[Reading], bool]]:
    def register(func: Callable[[Reading], bool]) -> Callable[[Reading], bool]:
        HANDLERS[name] = func
        return func
    return register


@handler("pressure")
def check_pressure(reading: Reading) -> bool:
    return reading.value < 90.0


@handler("temperature")
def check_temperature(reading: Reading) -> bool:
    return reading.value < 70.0


@handler("relay")
@audit("relay")
@retry(3)
def check_relay(reading: Reading) -> bool:
    return relay_state(reading)


class State(Enum):
    IDLE = auto()
    ARMED = auto()
    RUNNING = auto()
    STOPPED = auto()


TRANSITIONS = {
    (State.IDLE, "arm"): State.ARMED,
    (State.ARMED, "start"): State.RUNNING,
    (State.RUNNING, "trip"): State.STOPPED,
    (State.RUNNING, "stop"): State.STOPPED,
    (State.STOPPED, "reset"): State.IDLE,
}


def transition_table() -> list[str]:
    return [f"{state.name} --{action}--> {target.name}"
            for (state, action), target in TRANSITIONS.items()]


@dataclass(frozen=True)
class Event:
    at: str
    state: str
    action: str


@runtime_checkable
class Clock(Protocol):
    def now(self) -> str:
        ...


class FixedClock:
    def __init__(self, stamp: str = "2026-03-01T06:00:00") -> None:
        self.stamp = stamp

    def now(self) -> str:
        return self.stamp


def stream(source: Iterable[Reading | Alarm]) -> Iterator[tuple[int, Reading | Alarm]]:
    """Yield one numbered record at a time. Nothing is ever materialised."""
    for number, record in enumerate(source, start=1):
        yield number, record


@singledispatch
def describe(record: object) -> str:
    raise TypeError(f"no formatter for {type(record).__name__}")


@describe.register
def _(record: Reading) -> str:
    return f"reading {record.sensor}={record.value:.1f}"


@describe.register
def _(record: Alarm) -> str:
    return f"alarm {record.code}"


def best_strategy(strategies: dict[str, int]) -> str:
    return max(strategies, key=strategies.get)


class Interlock:
    def __init__(self, clock: Clock) -> None:
        self.clock = clock
        self.state = State.IDLE
        self.events: list[Event] = []

    def fire(self, action: str) -> State:
        try:
            target = TRANSITIONS[(self.state, action)]
        except KeyError as exc:
            raise TransitionError(f"{self.state.name} cannot {action}") from exc
        self.state = target
        self.events.append(Event(self.clock.now(), target.name, action))
        return target

    @contextmanager
    def session(self) -> Iterator["Interlock"]:
        previous = self.state
        JOURNAL.append("BEGIN")
        try:
            yield self
        except BaseException:
            self.state = previous
            JOURNAL.append("ROLLBACK")
            raise
        else:
            JOURNAL.append("COMMIT")

    def report(self, source: Iterable[Reading | Alarm], limit: int) -> list[str]:
        return [f"{number}. {describe(record)}"
                for number, record in islice(stream(source), limit)]

    def screen(self, name: str, reading: Reading) -> bool:
        return HANDLERS[name](reading)
